import { createRemoteJWKSet, jwtVerify } from "jose";
// @ts-ignore .open-next/worker.js is generated by the OpenNext build
import { default as handler } from "./.open-next/worker.js";

type Env = CloudflareEnv & { TEAM_DOMAIN?: string; POLICY_AUD?: string };

const keySets = new Map<string, ReturnType<typeof createRemoteJWKSet>>();

function teamOrigin(teamDomain: string): string {
  const withScheme = /^https?:\/\//.test(teamDomain) ? teamDomain : `https://${teamDomain}`;
  return new URL(withScheme).origin;
}

function keySet(origin: string) {
  let set = keySets.get(origin);
  if (!set) {
    set = createRemoteJWKSet(new URL("/cdn-cgi/access/certs", origin));
    keySets.set(origin, set);
  }
  return set;
}

async function signedIn(request: Request, teamDomain: string, audience: string): Promise<boolean> {
  const token = request.headers.get("Cf-Access-Jwt-Assertion");
  if (!token) return false;
  const origin = teamOrigin(teamDomain);
  try {
    await jwtVerify(token, keySet(origin), { issuer: origin, audience });
    return true;
  } catch {
    return false;
  }
}

function page(status: number, title: string, body: string): Response {
  const html = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${title} · Personal Finance</title>
<style>
  :root { color-scheme: light; }
  body { margin: 0; min-height: 100vh; display: grid; place-items: center; padding: 1.5rem;
    background: oklch(0.995 0.002 75); color: oklch(0.145 0.003 70);
    font: 15px/1.6 ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif; -webkit-font-smoothing: antialiased; }
  main { box-sizing: border-box; width: 100%; max-width: 34rem; padding: 2rem; border: 1px solid rgb(92 77 60 / 0.1);
    border-radius: 0.875rem; box-shadow: inset 0 1px 0 0 #fff, 0 1px 2px 0 rgb(0 0 0 / 0.04); }
  h1 { margin: 0; font-size: 1.125rem; font-weight: 500; }
  p { margin: 0.5rem 0 0; font-size: 0.875rem; color: oklch(0.455 0.005 70); }
  ol { margin: 1.25rem 0 0; padding-left: 1.25rem; font-size: 0.875rem; }
  li + li { margin-top: 0.5rem; }
  code { padding: 0.125rem 0.375rem; border-radius: 0.25rem; background: oklch(0.975 0.003 75); font-size: 0.8125rem; }
</style>
</head>
<body><main>${body}</main></body>
</html>`;
  return new Response(html, {
    status,
    headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" },
  });
}

const setupPage = () =>
  page(
    503,
    "Turn on sign-in",
    `<h1>Turn on sign-in first</h1>
<p>Your bank data stays hidden until only you can open this app.</p>
<ol>
  <li>In the Cloudflare dashboard, open <b>Workers &amp; Pages</b>. If it asks, click <b>Set up Zero Trust</b> and choose the Free plan.</li>
  <li>Open this Worker, then <b>Settings</b> &gt; <b>Domains &amp; Routes</b>, and click <b>Enable Cloudflare Access</b>.</li>
  <li>Choose <b>All traffic</b> and the <b>Cloudflare account</b> policy, then click <b>Apply Access</b>.</li>
  <li>Add the <b>JWKS</b> URL as the secret <code>TEAM_DOMAIN</code> and the <b>AUD tag</b> as the secret <code>POLICY_AUD</code>, in <b>Settings</b> &gt; <b>Variables and Secrets</b>.</li>
  <li>Open this page again and sign in.</li>
</ol>
<p>Full guide: docs/deploy.md in the repo.</p>`,
  );

const deniedPage = () =>
  page(403, "Sign in required", `<h1>Sign in required</h1><p>Open this app from its usual address and sign in.</p>`);

export default {
  async fetch(request, env, ctx) {
    if (!env.TEAM_DOMAIN || !env.POLICY_AUD) return setupPage();
    if (!(await signedIn(request, env.TEAM_DOMAIN, env.POLICY_AUD))) return deniedPage();
    return handler.fetch(request, env, ctx);
  },

  async scheduled(_controller, env, ctx) {
    const request = new Request("https://scheduled.internal/api/sync", { method: "POST" });
    ctx.waitUntil(handler.fetch(request, env, ctx));
  },
} satisfies ExportedHandler<Env>;
